// 6) Minimum SQL — run on Supabase if these don't already exist
// =====================================================================
/*
-- user_purchases: which user owns which course
CREATE TABLE IF NOT EXISTS public.user_purchases (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    course_id     uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE,
    status        text NOT NULL DEFAULT 'active',  -- active | trial | refunded
    granted_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NULL,
    source        text NULL,                       -- "stripe" | "manual_grant" | "promo"
    UNIQUE (user_id, course_id)
);

-- RLS: a user can only read their own purchase rows. Admins use service-role
-- which bypasses RLS automatically.
ALTER TABLE public.user_purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user_reads_own_purchases"
    ON public.user_purchases FOR SELECT
    USING (auth.uid() = user_id);

-- courses: read access is per-row driven by user_purchases for non-admins.
-- (If you'd rather keep the courses table publicly readable and gate ONLY
--  the library page, leave courses as-is — the server-side `.in("id",...)`
--  filter above is the actual security boundary for the library route.)
*/
